//! Shift Paste application: UI glue between the Slint windows and the core.

pub mod demo;
pub mod rows;

/// Code generated by Slint from `ui/*.slint`.
#[allow(clippy::all, clippy::todo, unused)]
pub mod ui {
    slint::include_modules!();
}

use shiftpaste_core::presets::Platform;

/// Key-cap labels for footers and menus, per OS.
pub fn key_labels() -> ui::Keys {
    match Platform::current() {
        Platform::MacOs => ui::Keys {
            r#mod: "⌘".into(),
            alt: "⌥".into(),
            shift: "⇧".into(),
            enter: "↩".into(),
        },
        _ => ui::Keys {
            r#mod: "Ctrl".into(),
            alt: "Alt".into(),
            shift: "⇧".into(),
            enter: "↵".into(),
        },
    }
}

/// Accent colour used for highlighted search matches.
pub fn accent_hex(dark: bool) -> &'static str {
    if dark {
        "#7aa7ff"
    } else {
        "#2563eb"
    }
}
